package com.example.techfix.ui;
public class AdminAppointmentDisplay { private final int appointmentId; private final String customerName,serviceName,branchName,date,status; public AdminAppointmentDisplay(int id,String customer,String service,String branch,String date,String status){this.appointmentId=id;this.customerName=customer;this.serviceName=service;this.branchName=branch;this.date=date;this.status=status;} public int getAppointmentId(){return appointmentId;} public String getCustomerName(){return customerName;} public String getServiceName(){return serviceName;} public String getBranchName(){return branchName;} public String getDate(){return date;} public String getStatus(){return status;} }